CREATE TABLE IF NOT EXISTS saliyah_sim_identities (id TEXT PRIMARY KEY,citizen_id TEXT NOT NULL REFERENCES saliyah_sim_citizens(id),status TEXT NOT NULL,issued_at TEXT NOT NULL,expires_at TEXT NOT NULL); CREATE TABLE IF NOT EXISTS saliyah_sim_job_applications (id TEXT PRIMARY KEY,citizen_id TEXT NOT NULL REFERENCES saliyah_sim_citizens(id),job_id TEXT NOT NULL REFERENCES saliyah_sim_jobs(id),status TEXT NOT NULL DEFAULT 'applied',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,decided_at TEXT)